<style>
.shop{font-family:var(--rv-font-ui)}.shop h1,.shop h2,.shop h3{font-family:var(--rv-font-display)!important}
.shop{max-width:1240px;margin:auto;padding:50px 24px 80px;color:#302a22}.shop h1,.shop h2,.shop h3{font-family:Holos,sans-serif}.shop h1{font-size:clamp(2rem,5vw,3.5rem);margin-bottom:24px}.shop a{color:inherit}.shop-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.shop-card,.shop-panel{background:#fffdf6;border:1px solid #d7cab3;border-radius:12px;padding:24px}.shop-card{display:flex;flex-direction:column;gap:14px}.shop-card img{width:100%;height:260px;object-fit:contain}.shop-card h2{font-size:1.5rem}.shop-price{font-size:1.4rem;font-weight:bold}.shop-btn{display:inline-block;background:#493a23;color:#fff!important;border:0;border-radius:6px;padding:12px 22px;text-decoration:none;cursor:pointer}.shop-btn:disabled{opacity:.5;cursor:default}.shop-secondary{background:#eee5d3;color:#302a22!important}.shop input,.shop select,.shop textarea{max-width:100%;border:1px solid #bbaa8b;border-radius:5px;padding:10px 12px;background:#fff;color:#302a22}.shop label{display:block;margin:16px 0 6px}.shop input:not([type=checkbox]),.shop textarea,.shop select{width:100%}.shop input[type=number]{width:85px}.shop form.inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.shop-filters{display:flex;gap:12px;align-items:end;margin-bottom:28px}.shop-filters>*{flex:1}.shop-filters button{flex:0}.shop-split{display:grid;grid-template-columns:1fr 1fr;gap:32px}.shop-row{display:flex;gap:20px;align-items:center;justify-content:space-between;padding:20px 0;border-bottom:1px solid #d7cab3}.shop-alert{background:#f3e8ce;border-left:4px solid #92733b;padding:16px;margin:20px 0}.shop-error{color:#9f2222}.shop-gallery{display:grid;gap:16px}.shop-gallery img{width:100%;height:auto;max-height:650px;object-fit:contain}.shop small{display:block}.shop table{width:100%;border-collapse:collapse}.shop td,.shop th{text-align:left;padding:12px 6px;border-bottom:1px solid #d7cab3}.shop .prose{line-height:1.75;overflow-wrap:anywhere}.shop .prose img{max-width:100%;height:auto}.shop-empty{padding:60px 24px;text-align:center}.shop-status{border-radius:30px;padding:8px 18px;background:#e9e0cb;display:inline-block}.shop .reading-prayer,.shop .reading-praise{border-left:3px solid #a98a4a;padding:20px 28px;background:#f3ead5;white-space:pre-line}.shop .pagination{justify-content:center;margin-top:32px}.shop ul.errors{padding-left:20px}
@media(max-width:900px){.shop-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.shop-split{grid-template-columns:1fr}.shop-filters{flex-wrap:wrap}.shop-filters>*{min-width:150px}}
@media(max-width:540px){.shop{padding:32px 16px 50px}.shop-grid{grid-template-columns:1fr}.shop-row{flex-wrap:wrap}.shop-card,.shop-panel{padding:18px}.shop h1{overflow-wrap:anywhere}.shop table{font-size:.85rem}.shop td,.shop th{padding:8px 3px}}
</style>
